python3 - <<'P'
import re,time
t=str(int(time.time()))
for fn in ['index.html','chat.html','system.html']:
    s=open(fn,encoding='utf-8').read()
    s=re.sub(r'nox-hud-s1\.js\?v=[0-9]*','nox-hud-s1.js?v='+t,s)
    if 'nox-hud-s1.css' not in s: s=s.replace('</body>','<link rel="stylesheet" href="./nox-hud-s1.css?v='+t+'">\n</body>',1)
    else: s=re.sub(r'nox-hud-s1\.css\?v=[0-9]*','nox-hud-s1.css?v='+t,s)
    open(fn,'w',encoding='utf-8').write(s)
for k,v in {'index':'HUD усилен: анимированное появление, свечение, линия-сканер, моноширинные подписи.','chat':'HUD усилен (как index); теги быстрых команд проверены на 390.','system':'HUD усилен + три ECharts gauge (GPU, VRAM, ДИСК) из /api/nox-live.'}.items():
    open('qa/rework/%s.fixed'%k,'a',encoding='utf-8').write('\nS1: '+v+'\n')
print('w15 ok')
P
